gc9r(){return"\u0645\u0648\u0636\u0648\u0639 \u0631\u0627 \u0628\u0646\u0648\u06cc\u0633\u06cc\u062f \u0648 Enter \u0628\u0632\u0646\u06cc\u062f\u2026"},
gc9s(){return"Enter \u0628\u0631\u0627\u06cc \u0627\u0631\u0633\u0627\u0644 \xb7 Esc \u0628\u0631\u0627\u06cc \u0628\u0633\u062a\u0646 \xb7 Hold Q \u0633\u067e\u0633 AI"},
gc9q(){return"AI \u0631\u0627 \u062a\u0627\u06cc\u067e \u06a9\u0646\u06cc\u062f\u2026"},
gc9t(){return"\u0628\u0631\u0627\u06cc \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0627\u0632 \u062f\u0633\u062a\u06cc\u0627\u0631 \u0647\u0648\u0634\u0645\u0646\u062f \u0627\u0628\u062a\u062f\u0627 \u06cc\u06a9 \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u0631\u0627 \u0628\u0627\u0632 \u06a9\u0646\u06cc\u062f."},
gc9u(){return"\u0628\u0631\u0627\u06cc \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0627\u0632 \u062f\u0633\u062a\u06cc\u0627\u0631 \u0647\u0648\u0634\u0645\u0646\u062f \u0648\u0627\u0631\u062f \u062d\u0633\u0627\u0628 \u0634\u0648\u06cc\u062f."},
